; Flak gun positions
; $6db1-$6dec

; Adds a flak gun of the new map row. In: Y = map column. Uses the first free slot 7-1, else slot 0.
add_flak_gun
        ldx #$08
add_flak_gun_find
        dex
        beq add_flak_gun_store
        lda gun_x,x
        bne add_flak_gun_find
add_flak_gun_store
        tya                             ; Gun x = column * 4 + 15, gun y = $2b.
        asl
        asl
        clc
        adc #$0f
        sta gun_x,x
        lda #$2b
        sta gun_y,x
