; Moves the eight flak gun positions with the ground: x - 1, y + 2. Clears a gun at y >= $c8.
scroll_flak_guns
        ldx #$07
scroll_flak_guns_loop
        lda gun_x,x
        beq scroll_flak_guns_next
        dec gun_x,x
        inc gun_y,x
        inc gun_y,x
        lda gun_y,x
        cmp #$c8
        bcc scroll_flak_guns_next
        lda #$00
        sta gun_x,x
        jmp scroll_flak_guns_next
scroll_flak_guns_next
        dex
        bpl scroll_flak_guns_loop
        rts
